-- GENERATED by `wfj generate` from data/gossip/gossip-01.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["01054ee3e7c7dada"] = { "Parla con Ironus, {name}. Sarà lui ad addestrarti nella via del Fabbro d'Armi.", "." },
  ["010a74a8f479f629"] = { "%s riporta in vita un servitore non morto!", "." },
  ["010cbd3ff9786a32"] = { "<Illaya ti sorride con calore.>\n\nMi rallegra che tu sia <tornato/tornata> a parlarmi, <figlio/figlia> dei venti. L'ho capito fin dal primo istante in cui sei <comparso/comparsa> al mio cospetto: sei forte nella vista celeste. Anche per <uno/una> <Sciamano/Sciamana>, mostri un'attitudine particolare per il nostro dono.\n\nVieni, parliamo del mandato dei Windshapers, della natura delle nostre lotte su Zephras e della triste sorte della nostra gente.", "." },
  ["010d2df78ab0330d"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare una ⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧?", "." },
  ["010f674d09e90c89"] = { "Ogni professione ha qualcosa da offrire al tuo accampamento, perfino i pescatori!", "." },
  ["0110fdc2e812a4b1"] = { "Hai la mia approvazione, {name}: forgi lame meglio di chiunque abbia addestrato da anni. Ma se vuoi fare un'arma vera, devi parlare con Myolor Sunderfury. Quel Nano ti metterà sulla strada giusta.", "." },
  ["011bff79d40b7a68"] = { "%s segue felice {name}: ora è il suo nuovo germoglio.", "." },
  ["011dc01ec86cf5e1"] = { "La bandiera dell'⟦Alliance=Alleanza⟧ è tornata alla sua base!", "." },
  ["012385b40afa4648"] = { "In gran parte, sì. Quello che abbiamo tutti in comune è che non abbiamo nessun altro posto dove andare e che preferiamo rubare piuttosto che farci schiavi di qualche culto folle.", "." },
  ["012df5f1b385c6a9"] = { "Proviamo a piantarlo in un po' del mio terriccio speciale, già preparato...", "." },
  ["012fa56fb7751268"] = { "Noi troll Zandalari siamo giunti qui da isole lontane, perché non possiamo ignorare la minaccia che ora incombe sul nostro mondo.\n\nIl capo della nostra spedizione, Molthor, ci ha condotti all'⟦Yojamba Isle=Isola di Yojamba⟧, lungo le coste settentrionali di Rovotorto, e proprio ora sta reclutando coraggiosi eroi che si avventurino nell'antica città troll... ⟦Zul'Gurub=Zul'gurub⟧.", "." },
  ["0131d9eba36bb132"] = { "{class}, consumerò la tua luce!", "." },
  ["013215d7b24991df"] = { "La ⟦Cathedral of Light=Cattedrale della Luce⟧ è il centro di tutte le pratiche di guarigione di ⟦Stormwind=Roccavento⟧. Lì troverai Shaina Fuller, che ti aiuterà a imparare quest'arte.", "." },
  ["013681a52734636a"] = { "Che questa aura malvagia sia bandita da questo manufatto!", "." },
  ["013a291b6334c4aa"] = { "Ti do il benvenuto nel mio negozio, {class}. Cosa possono fare per te i fratelli Goodstitch?", "." },
  ["0144f1fa857c9c29"] = { "Troverai Pyall Silentstride nella grande tenda nell'angolo nord-ovest del villaggio. Può insegnarti ciò che brami.", "." },
  ["014573843b7a6aa7"] = { "Ho troppo da fare e troppo poco tempo per farlo, {race}! Ti prego, levati di mezzo.", "." },
  ["014a131845a36b73"] = { "Seguitemi, amici. Al Castello di ⟦Stormwind=Roccavento⟧!", "." },
  ["014ea8506ecfba38"] = { "Devo smettere di fumare! Dammi un minuto per riprendere fiato.", "." },
  ["01530ff61a3b291e"] = { "Ecco fatto: una tenda da campo tutta tua. Alla gente non piace granché vedere tende montate in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", "." },
  ["01531197b9f4a36e"] = { "Strano. Molto strano...", "." },
  ["0159c2043d8a2169"] = { "Il Flagello è sconfitto! ⟦Darrowshire=Borgo di Darrow⟧ è salvo!", "." },
  ["0159d6ad19a29743"] = { "Ah sì, ne ho sentito parlare.", "." },
  ["016095ec4b95cfb0"] = { "Le luci lampeggianti sulla console di controllo indicano che le valvole di controllo principali non sono state chiuse.", "." },
  ["0160ced2272c8209"] = { "Cosa porta un tauren nelle ⟦Plaguelands=Terre Infette⟧?", "." },
  ["0162e1a5f228d477"] = { "Quando la terra smise di tremare, le sue vere intenzioni vennero alla luce. Eravamo in trappola, e lui ci stava lentamente prosciugando i poteri.", "." },
  ["0165268681f870fb"] = { "Reginald, sai che non posso lasciarti passare.", "." },
  ["016750ec7b4e4f2f"] = { "Premi! Venite a prendere i vostri premi! Venite qui e consegnate i vostri Darkmoon Faire Prize Ticket in cambio di premi preziosi!", "." },
  ["01731eed492d0370"] = { "Fa piacere vedere altri che combattono il Flagello a Stratholme, perché è qui che è più forte.\n\nSalute. Sono Aurius. Un tempo appartenevo ai paladini della ⟦Silver Hand=Mano d'Argento⟧, ma come altri la cui fede vacillò... caddi in disgrazia. Il Flagello mi sedusse e per poco non mi trasformò in un cavaliere della morte!\n\nAvvertendo infine il pericolo, fuggii in questa cappella. È un luogo sacro, dove il primo paladino, Uther il Portatore di Luce, fu ordinato nell'ordine della ⟦Silver Hand=Mano d'Argento⟧.", "." },
  ["017801fec3ae9eb6"] = { "Il tuo animaletto è splendido, Gerard, ma secondo me le servirebbe un collare con un campanello.", "." },
  ["01789f6449ae5594"] = { "Urrà, {name}!", "." },
  ["0178c5ae1faa1830"] = { "Grazie per le spore, {name}. Ora sono pronte per il trasporto.", "." },
  ["0185c61f05c24da5"] = { "Ragnaros regnerà sovrano!", "." },
  ["018b6e02cff263fe"] = { "Come se avessi tutta l'eternità.", "." },
  ["018bb36fdcebabe9"] = { "Beh... per poco non mi impressionavi. Immagino di poter trovare il tempo per qualche lezione...", "." },
  ["0198abafcd00877a"] = { "Sappi che, ovunque tu li trovi nel mondo, stanno proteggendo qualcosa di importante, come fu loro affidato tanto tempo fa.", "." },
  ["019b2d4d090fa521"] = { "Altri trogg! Tienili lontani mentre preparo gli esplosivi!", "." },
  ["019ba462df3cbfa4"] = { "Oh, è semplicemente terribile, terribile, orrendo! Ti verrà un COLPO quando lo vedrai, Vivian.", "." },
  ["019c2e2423465de2"] = { "{name} UCCIDE! <Lui/Lei> uccide te ora! SCAPPA! SCAPPA!", "." },
  ["01a7abb927206747"] = { "Mi aiuterai?", "." },
  ["01ada4f10aa5a990"] = { "%s inizia a crescere!", "." },
  ["01ae96a622324e21"] = { "Questo posto è sicuro, i Defias possono prenderselo! Chiama gli altri.", "." },
  ["01bb3777069c1701"] = { "Se ti serve aiuto per sopravvivere nei boschi, faresti meglio a non allontanarti troppo dalle mura della città. Se invece hai intenzione di allontanarti, è meglio che tu faccia due chiacchiere con Malygen nell'⟦Cenarion Enclave=Enclave Cenariana⟧, così imparerai ad accendere un fuoco da campo come si deve.", "." },
  ["01ce973af48d2c8e"] = { "{name}! QUEST'AREA È INTERDETTA!", "." },
  ["01d161a9b59a4f04"] = { "Come puoi amarmi, Annalise? Guardami. Non sono più l'uomo che conoscevi.", "." },
  ["01d182790517060e"] = { "No, Longears non è il mio vero nome. E non ti dirò qual è, quindi non chiedermelo.", "." },
  ["01d2b0e56616e6f8"] = { "Ehehe! Le cose fanno bum!", "." },
  ["01d3c35e9e6cff33"] = { "EVVAI!", "." },
  ["01d554846bfd1211"] = { "Tutt'a un tratto sei un «Difensore dell'⟦Alliance=Alleanza⟧», eh?! Beh, immagino che adesso vorrai andare alla ⟦Champions' Hall=Sala dei Campioni⟧. È giù a Old Town, ma non ti faranno entrare se non sei un ufficiale, quindi forse dovrai accontentarti di parlare con l'ufficiale Areyn fuori. Circolare, ora.", "." },
  ["01e63eaee057f452"] = { "Ah, lo strato protettivo è quasi svanito. Lo sentite, eroi? Quello... Quello è il suono dell'inevitabile. Delle vostre speranze e dei vostri sogni schiacciati sotto il peso del mio essere.", "." },
  ["01ea16447d200bad"] = { "Questa è la risposta alla prima domanda della prima catena.", "." },
  ["01f28add3e87df12"] = { "Ti manda il maresciallo Haggard? Perché non l'hai detto subito?\n\nAh, il buon vecchio Haggard. Povero diavolo, tra non molto sarà completamente cieco. Comunque, fammi vedere cos'hai lì.", "." },
  ["01f4642bba22812b"] = { "In guardia, <amico/amica>. La dama drago non si arrenderà senza combattere.", "." },
  ["01f847b8f88257d1"] = { "Forse, tra la nostra gente, nessun altro shen'dorei ancora in vita ha scambiato con lui più di qualche parola.\n\nL'ho servito come capitano delle sue Empyrean Blades per quasi nove secoli, fino a quando... ci ha lasciati.\n\nEppure non posso dire davvero di averlo «conosciuto». È sempre stato un uomo riservato e solitario. Passava gran parte del tempo da solo o in comunione con gli spiriti, nelle guglie alte sopra lo Shrine of the Four Winds... il luogo che il culto ora chiama «Shrine of Akir».", "." },
  ["01f9cd5ff93bab79"] = { "Wow... tu SEI ver<o/a> <re/regina>! Io mai pensato di vedere questo guanto in mia vita! Sembra che non ha più mojo... forse elfo inquietante ha provato a rovinare guanto. Be', io dico HAR HAR a lui!\n\nGuarda: questo segno su guanto è segno magico dei vecchi vecchi VECCHI tempi, più vecchio dei Gordok, dicono. Be', come Capitano dei Gordok, noi tutti impariamo una cosa più e più volte: come far tornare in vita segno e ridare potere a guanto!\n\nIo lo faccio per te, <re/regina>! Ecco, prendi guanto e regna PER SEMPRE!", "." },
  ["01f9f81177c47ed5"] = { "Mi sto solo scaldando!", "." },
  ["01ff2fa0e83c3667"] = { "Da dove cominciare? La nostra casa sta cedendo. Le protezioni sono cadute e le tre province hanno iniziato ad allontanarsi l'una dall'altra. Non molto tempo fa, le guglie di Shen'dramar si vedevano dalla torre di guardia occidentale. Non più. Giorno dopo giorno, i piloni del vento che ancorano la nostra casa a questo piano si indeboliscono...", "." },
})
